let visible=[];
let toastTimer;
const formatSize = p => p.size >= 1024*1024 ? (p.size/1024/1024).toFixed(1)+' MB' : (p.size/1024).toFixed(1)+' KB';
const shutter = v => v == null ? '—' : v >=1 ? v+' s' : '1/'+Math.round(1/v)+' s';
const aperture = v => v == null ? '—' : 'f/'+Number(v).toFixed(v%1?1:0);
const shortDate = v => !v ? '未提供' : v.slice(0,10).replaceAll('-','.');
const dateTime = v => !v ? '未提供' : v.slice(0,10).replaceAll('-','.')+'  '+v.slice(11,19);
const selectedPhoto = () => state.photos.find(p=>p.id===state.selected);
const has = v => v !== null && v !== undefined && v !== '';
function iconize(){ if(window.lucide) window.lucide.createIcons({attrs:{'stroke-width':1.65}}); }
function sortVal(p){return state.sort==='pixels'?p.width&&p.height?p.width*p.height:null:state.sort==='ratio'?p.width&&p.height?p.width/p.height:null:state.sort==='starred'?Number(p.starred):p[state.sort];}
function basePhotos(){return state.photos.filter(p=>state.folder==='all'||p.folder===state.folder);}
function calcVisible(){
 return basePhotos().filter(p=>
 (!state.query||p.name.toLowerCase().includes(state.query.toLowerCase()))&&
 (!state.exts.length||state.exts.includes(p.ext))&&(!state.rawOnly||rawExts.has(p.ext))&&
 (!state.camera||p.camera===state.camera)&&(!state.orientation||(state.orientation==='portrait'?p.height>p.width:p.width>=p.height))&&
 (!state.isoMin||has(p.iso)&&p.iso>=Number(state.isoMin))&&(!state.isoMax||has(p.iso)&&p.iso<=Number(state.isoMax))&&
 (!state.date||p.captured?.startsWith(state.date))&&(!state.starred||p.starred)
 ).sort((a,b)=>{let av=sortVal(a),bv=sortVal(b);if(!has(av)&&!has(bv))return collator.compare(a.name,b.name);if(!has(av))return 1;if(!has(bv))return -1;let c=typeof av==='number'?av-bv:collator.compare(av,bv);return c?(state.asc?c:-c):collator.compare(a.name,b.name);});
}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,2800);}
function persist(){try{sessionStorage.setItem('jianshan-ui',JSON.stringify({theme:document.documentElement.dataset.theme,info:state.info}));}catch{}}
function setInfo(open){state.info=open;$('#app').classList.toggle('inspector-closed',!open);$('#app').classList.toggle('inspector-mobile',open);$('#infoBtn').classList.toggle('active',open);persist();}
function updateCameraOptions(){const sel=$('#cameraFilter');sel.innerHTML='<option value="">所有相机</option>'+[...new Set(basePhotos().map(p=>p.camera).filter(Boolean))].sort().map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');sel.value=state.camera;}
function formatChips(){const base=basePhotos();const exts=[...new Set(base.map(p=>p.ext))];const order=['JPG','ARW','CR3','NEF','RAF','DNG','PNG'];exts.sort((a,b)=>(order.indexOf(a)<0?99:order.indexOf(a))-(order.indexOf(b)<0?99:order.indexOf(b)));const raw=base.filter(p=>rawExts.has(p.ext)).length;$('#formatRow').innerHTML=`<button class="format-chip ${!state.exts.length&&!state.rawOnly?'active':''}" data-format="all">全部<small>${base.length}</small></button>${raw?`<button class="format-chip ${state.rawOnly?'active':''}" data-format="raw">RAW<small>${raw}</small></button>`:''}${exts.map(ext=>`<button class="format-chip ${state.exts.includes(ext)?'active':''}" data-format="${esc(ext)}">.${esc(ext)}<small>${base.filter(p=>p.ext===ext).length}</small></button>`).join('')}`;}
function advancedCount(){return [state.camera,state.orientation,state.isoMin||state.isoMax,state.date,state.starred].filter(Boolean).length;}
function renderActiveFilters(){const filters=[];if(state.camera)filters.push(['camera',state.camera]);if(state.orientation)filters.push(['orientation',state.orientation==='portrait'?'纵向':'横向']);if(state.isoMin||state.isoMax)filters.push(['iso',`ISO ${state.isoMin||'0'}–${state.isoMax||'不限'}`]);if(state.date)filters.push(['date',state.date]);if(state.starred)filters.push(['starred','已加星标']);const el=$('#activeFilters');el.hidden=!filters.length;el.innerHTML=filters.map(([key,label])=>`<button class="active-filter" data-remove-filter="${key}">${esc(label)}${icon('x')}</button>`).join('')+(filters.length?'<button class="subtle-link" id="clearAllFilters">清除全部</button>':'');const c=advancedCount();$('#filterCounter').textContent=c;$('#filterCounter').hidden=!c;}
function photoMedia(p,cls=''){return p.src?`<img class="${cls}" src="${esc(p.src)}" alt="${esc(p.name)}" loading="lazy" draggable="false">`:`<div class="missing-preview">${icon('file-image')}<span>${rawExts.has(p.ext)?'RAW 预览待接入':'格式暂不支持'}</span></div>`;}
function renderGrid(){
 $('#photoGrid').innerHTML=visible.map(p=>`<div class="photo-tile ${p.id===state.selected?'selected':''}" role="listitem"><button class="photo-button" data-select="${esc(p.id)}" aria-label="${esc(p.name)}${p.id===state.selected?'，已选择':''}" aria-pressed="${p.id===state.selected}"><div class="photo-frame">${photoMedia(p)}<span class="photo-type">${rawExts.has(p.ext)?'RAW':esc(p.ext)}</span>${p.id===state.selected?`<span class="selected-check">${icon('check')}</span>`:''}</div><div class="photo-name"><span>${esc(p.name)}</span></div><div class="photo-meta"><span>${shortDate(p.captured)}</span><span>·</span><span>${formatSize(p)}</span></div></button><button class="tile-star ${p.starred?'starred':''}" data-star="${esc(p.id)}" aria-label="${p.starred?'取消星标':'添加星标'} ${esc(p.name)}">${icon('star')}</button></div>`).join('');
}
function row(key,value){return `<div class="metadata-row"><span class="key">${key}</span><span class="value">${esc(value??'未提供')}</span></div>`;}
function metadata(p){return [['文件名',p.name],['文件格式',p.ext],['文件大小',formatSize(p)],['相机型号',p.camera??'未提供'],['镜头型号',p.lens??'未提供'],['拍摄时间',dateTime(p.captured)],['ISO',p.iso??'未提供'],['快门',shutter(p.shutter)],['光圈',aperture(p.aperture)],['焦距',p.focal?p.focal+' mm':'未提供'],['图像尺寸',p.width&&p.height?`${p.width} × ${p.height}`:'未提供'],['像素总数',p.width&&p.height?(p.width*p.height/1e6).toFixed(1)+' MP':'未提供'],['修改时间',dateTime(p.modified)],['色彩空间',p.space??'未提供'],['GPS',p.gps??'未提供']];}
function renderInspector(){
 const p=selectedPhoto();if(!p||!visible.length){$('#inspectorContent').innerHTML='';return;}
 $('#inspectorContent').innerHTML=`<div class="inspector-preview">${photoMedia(p)}<button data-action="open-single" aria-label="打开单张视图">${icon('expand')}</button></div><h3 class="inspector-filename">${esc(p.name)}</h3><div class="file-tags"><span class="type-tag">${esc(p.ext)}</span><span>${formatSize(p)}</span><span>·</span><span>${p.width&&p.height?(p.width*p.height/1e6).toFixed(1)+' MP':'尺寸未读取'}</span></div><div class="camera-line">${icon('camera')}<span>${esc(p.camera??'未提供相机信息')}</span></div><div class="lens-line">${esc(p.lens??'未提供镜头信息')}</div><div class="exposure-stats"><div class="exposure-stat"><strong>${aperture(p.aperture)}</strong><span>光圈</span></div><div class="exposure-stat"><strong>${shutter(p.shutter).replace(' s','')}</strong><span>快门 / s</span></div><div class="exposure-stat"><strong>${p.iso??'—'}</strong><span>ISO</span></div></div><section class="metadata-section"><h3>拍摄参数</h3>${row('拍摄时间',dateTime(p.captured))}${row('焦距',p.focal?p.focal+' mm':'未提供')}${row('曝光补偿',p.demo&&has(p.iso)?'0 EV':'未提供')}${row('测光模式',p.demo&&has(p.iso)?'多区测光':'未提供')}</section><section class="metadata-section"><h3>文件信息</h3>${row('图像尺寸',p.width&&p.height?`${p.width.toLocaleString()} × ${p.height.toLocaleString()}`:'未提供')}${row('色彩空间',p.space??'未提供')}${row('修改时间',dateTime(p.modified))}${row('预览来源',p.src?(rawExts.has(p.ext)?'相机内嵌预览':'原文件'):'暂不可预览')}</section><div class="rating-row"><span>标记</span><button class="star-action ${p.starred?'starred':''}" data-star="${esc(p.id)}">${icon('star')}${p.starred?'已加星标':'添加星标'}</button></div><div class="metadata-footer"><button data-action="all-metadata">查看全部元数据${icon('arrow-up-right')}</button><span>${p.demo?'示例参数':'本地文件'}</span></div>`;
}
function renderSingle(){const p=selectedPhoto();if(!p||!visible.length)return;$('#singleImage').src=p.src||'';$('#singleImage').hidden=!p.src;$('#singleImage').alt=p.name;$('#singleName').textContent=p.name;$('#previewMode').textContent=rawExts.has(p.ext)?(p.demo?'相机内嵌预览 · 示例':'RAW 预览待接入'):'原文件预览';$('#miniFolderName').textContent=state.folderName;const pos=visible.findIndex(x=>x.id===p.id);$('#singlePosition').textContent=`${pos+1} / ${visible.length}`;$('#prevBtn').disabled=pos<=0;$('#nextBtn').disabled=pos>=visible.length-1;$('#singleImage').style.transform=`scale(${state.zoom})`;$('#imageStage').classList.toggle('zoomed',state.zoom>1);$('#zoomFit').textContent=state.zoom===1?'适应窗口':Math.round(state.zoom*100)+'%';$('#filmstrip').hidden=!state.filmstrip;$('#miniFilmstripButton').classList.toggle('active',state.filmstrip);$('#filmstrip').innerHTML=visible.map(f=>`<button class="film-item ${f.id===p.id?'selected':''}" data-film="${esc(f.id)}" aria-label="切换至 ${esc(f.name)}" aria-pressed="${f.id===p.id}">${photoMedia(f)}</button>`).join('');}
function render(){
 visible=calcVisible();if(!visible.some(p=>p.id===state.selected))state.selected=visible[0]?.id??null;$('#app').classList.toggle('single-mode',state.view==='single');$('#app').classList.toggle('grid-mode',state.view==='grid');$('#app').classList.toggle('grid-format-open',state.formatOpen);$('#app').classList.toggle('sidebar-collapsed',!state.sidebar);$('#app').classList.toggle('inspector-closed',!state.info);
 $('#app').classList.toggle('is-empty',!visible.length);$('#photoGrid').hidden=state.view!=='grid'||!visible.length;$('#singleArea').hidden=state.view!=='single'||!visible.length;$('#emptyState').hidden=!!visible.length;$('#gridView').classList.toggle('active',state.view==='grid');$('#singleView').classList.toggle('active',state.view==='single');$('#thumbnailControl').hidden=state.view!=='grid';
 const base=basePhotos();$('#navCount').textContent=base.length;$('#starCount').textContent=base.filter(p=>p.starred).length;$('#folderCount').textContent=base.length;$('#resultCount').textContent=visible.length===base.length?`${visible.length} 张图片`:`${visible.length} / ${base.length} 张图片`;$('#selectionCount').textContent=visible.length?'已选择 1 张':'未选择';$('#sortLabel').textContent=sortDefs.find(x=>x[1]===state.sort)?.[2].replace('（自然排序）','');$('#orderBtn').innerHTML=icon(state.asc?'arrow-up':'arrow-down');$('#orderBtn').title=state.asc?'当前升序 · 点击降序':'当前降序 · 点击升序';$('#orderBtn').setAttribute('aria-label',state.asc?'当前升序，切换为降序':'当前降序，切换为升序');
 $('#allPhotos').classList.toggle('active',!state.starred);$('#favoriteNav').classList.toggle('active',state.starred);$('#starFilter').checked=state.starred;formatChips();renderActiveFilters();renderGrid();renderInspector();if(state.view==='single')renderSingle();iconize();persist();
}
function setView(view){if(state.view==='grid'&&view==='single')state.gridScroll=$('#galleryArea').scrollTop;state.view=view;state.zoom=1;closeMiniTools();render();if(view==='grid'){$('#galleryArea').scrollTop=state.gridScroll;}else{$('#galleryArea').scrollTop=0;}}
function move(delta){if(!visible.length)return;const i=visible.findIndex(p=>p.id===state.selected);const next=Math.max(0,Math.min(visible.length-1,i+delta));state.selected=visible[next].id;state.zoom=1;render();if(state.view==='grid')$(`[data-select="${state.selected}"]`)?.scrollIntoView({block:'nearest'});else $(`[data-film="${state.selected}"]`)?.scrollIntoView({block:'nearest',inline:'nearest'});}
function clearFilters(){state.exts=[];state.rawOnly=false;state.query='';state.camera='';state.orientation='';state.isoMin='';state.isoMax='';state.date='';state.starred=false;$('#search').value='';$('#cameraFilter').value='';$('#orientationFilter').value='';$('#isoMin').value='';$('#isoMax').value='';$('#dateFilter').value='';$('#starFilter').checked=false;render();}
function closeMiniTools(){$('#miniToolsMenu').hidden=true;}
function closePopovers(){['sort','filter'].forEach(s=>{$('#'+s+'Popover').hidden=true;$('#'+s+'Btn').setAttribute('aria-expanded','false');});closeMiniTools();}
function popover(kind){const el=$('#'+kind+'Popover');const open=el.hidden;closePopovers();el.hidden=!open;$('#'+kind+'Btn').setAttribute('aria-expanded',String(open));}
function openDialog(title,content){$('#dialogTitle').textContent=title;$('#dialogContent').innerHTML=content;$('#dialog').showModal();iconize();}
function allMetadata(){const p=selectedPhoto();if(!p)return;openDialog('全部元数据',`<p>${p.demo?'当前为示例图片；下列拍摄参数用于演示信息布局。':'当前原型仅读取浏览器能提供的文件属性，不解析本地 EXIF。'}</p><table>${metadata(p).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${esc(v)}</td></tr>`).join('')}</table>`);}
function star(id){const p=state.photos.find(x=>x.id===id);if(p){p.starred=!p.starred;render();}}
async function copyInfo(){const p=selectedPhoto();if(!p)return;try{await navigator.clipboard.writeText(metadata(p).map(([k,v])=>k+': '+v).join('\n'));toast('已复制拍摄与文件信息');}catch{allMetadata();toast('可在元数据面板中选择并复制文本');}}
function folder(kind){$('[data-folder="all"] span:last-child').textContent=state.local?state.folderName:'山野 · 秋日';$$('[data-folder="landscape"],[data-folder="forest"]').forEach(b=>b.hidden=state.local);$('.demo-note>span:nth-child(2)').textContent=state.local?'本地文件夹':'示例文件夹';state.folder=kind;state.folderName=kind==='landscape'?'山与湖':kind==='forest'?'林间漫步':state.local?state.folderName:'山野 · 秋日';$('#folderTitle').innerHTML=esc(state.folderName)+'<span class="folder-count" id="folderCount"></span>';$('#breadcrumbFolder').textContent=state.folderName;$$('[data-folder]').forEach(b=>b.classList.toggle('selected',b.dataset.folder===kind));clearFilters();updateCameraOptions();}
function about(){openDialog('关于这份 UI 原型','<p><b>见山</b>是图片查看器的临时名称。这份原型用来讨论布局、浏览路径和信息密度，最终应用计划使用 MyGo 原生 UI。</p><p>可体验网格 / 单张、胶片栏、16 种排序、后缀多选、相机 / ISO / 日期筛选、信息面板、星标和浅深色外观。</p><p><b>示例照片来自 Unsplash，文件名与摄影参数均为演示数据。</b>本地文件夹入口可浏览浏览器支持的图片；当前未接入 RAW 解码与 EXIF 解析。</p><p>快捷键：方向键切图；Enter / Space 打开；G 返回网格；I 开关信息；F 沉浸查看；Esc 退出。</p><p><a href="../photo-viewer-research.html" target="_blank" rel="noopener">阅读调研与设计说明 ↗</a></p>');}
function bind(){
 $('#sortOptions').innerHTML=sortDefs.map((s,i)=>`${i===0||s[0]!==sortDefs[i-1][0]?`<div class="sort-group-label">${s[0]}</div>`:''}<button class="sort-option ${state.sort===s[1]?'active':''}" data-sort="${s[1]}"><span>${s[2]}</span>${state.sort===s[1]?icon('check'):''}</button>`).join('');
 $('#sortBtn').onclick=()=>{bindSort();popover('sort');};$('#filterBtn').onclick=()=>popover('filter');$('#orderBtn').onclick=()=>{state.asc=!state.asc;render();};$('#gridView').onclick=()=>setView('grid');$('#singleView').onclick=()=>setView('single');$('#backToGrid').onclick=()=>setView('grid');$('#prevBtn').onclick=()=>move(-1);$('#nextBtn').onclick=()=>move(1);$('#infoBtn').onclick=()=>setInfo(!state.info);$('#formatToggle').onclick=()=>{state.formatOpen=!state.formatOpen;render();};$('#miniInfoButton').onclick=()=>setInfo(!state.info);$('#closeInfoBtn').onclick=()=>setInfo(false);$('#sidebarBtn').onclick=()=>{state.sidebar=!state.sidebar;render();};$('#miniOpen').onclick=()=>$('#folderInput').click();$('#miniFolderButton').onclick=()=>{state.sidebar=!state.sidebar;render();};$('#miniToolsButton').onclick=()=>{$('#miniToolsMenu').hidden=!$('#miniToolsMenu').hidden;};$('#miniFilmstripButton').onclick=()=>{state.filmstrip=!state.filmstrip;render();};$('#search').oninput=e=>{state.query=e.target.value;render();};$('#thumbSize').oninput=e=>document.documentElement.style.setProperty('--thumb',e.target.value+'px');
 ['camera','orientation','isoMin','isoMax','date'].forEach(k=>{const el=$('#'+(k==='camera'?'cameraFilter':k==='orientation'?'orientationFilter':k==='date'?'dateFilter':k));el.addEventListener(k==='isoMin'||k==='isoMax'?'input':'change',e=>{state[k]=e.target.value;render();});});$('#starFilter').onchange=e=>{state.starred=e.target.checked;render();};$('#resetAdvanced').onclick=()=>{state.camera=state.orientation=state.isoMin=state.isoMax=state.date='';state.starred=false;$('#cameraFilter').value=$('#orientationFilter').value=$('#isoMin').value=$('#isoMax').value=$('#dateFilter').value='';render();};$('#allPhotos').onclick=()=>{state.starred=false;render();};$('#favoriteNav').onclick=()=>{state.starred=!state.starred;render();};$('#clearEmpty').onclick=clearFilters;
 $('#openFolder').onclick=()=>$('#folderInput').click();$('#folderInput').onchange=e=>loadLocalFiles([...e.target.files]);$('#demoFolder').onclick=()=>{state.photos=demoPhotos;state.local=false;folder('all');$('#folderDescription').textContent='把山间的光，留在这一帧。';$('.micro-label').textContent='DEMO';};$('#aboutBtn').onclick=about;$('#keyboardBtn').onclick=()=>openDialog('键盘快捷键','<table>'+[['← / →','上一张 / 下一张'],['↑ / ↓','网格上下移动'],['Enter / Space','进入单张查看'],['G / Esc','返回网格'],['I / ⌘I','显示 / 隐藏信息'],['F','切换沉浸查看'],['S','为当前图片加星标'],['⌘F','搜索文件名'],['⌘O','打开文件夹']].map(([k,v])=>`<tr><td>${k}</td><td>${v}</td></tr>`).join('')+'</table>');$('#dialogClose').onclick=()=>$('#dialog').close();$('#dialog').onclick=e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#dialog').close();}};$('#copyInfoBtn').onclick=copyInfo;
 $('#zoomIn').onclick=()=>{state.zoom=Math.min(3,state.zoom+.25);renderSingle();iconize();};$('#zoomOut').onclick=()=>{state.zoom=Math.max(.5,state.zoom-.25);renderSingle();iconize();};$('#zoomFit').onclick=()=>{state.zoom=1;renderSingle();iconize();};$('#fullscreenBtn').onclick=()=>{state.fullscreen=!state.fullscreen;$('#app').classList.toggle('fullscreen',state.fullscreen);};
 document.addEventListener('click',e=>{const t=e.target.closest('button');if(t?.dataset.miniAction){const action=t.dataset.miniAction;closeMiniTools();if(action==='grid')setView('grid');else if(action==='sort'){setView('grid');setTimeout(()=>{bindSort();popover('sort');},0);}else if(action==='folder')$('#folderInput').click();return;}if(t?.dataset.select){state.selected=t.dataset.select;render();}else if(t?.dataset.star)star(t.dataset.star);else if(t?.dataset.film){state.selected=t.dataset.film;state.zoom=1;render();}else if(t?.dataset.format){const f=t.dataset.format;if(f==='all'){state.exts=[];state.rawOnly=false;}else if(f==='raw'){state.rawOnly=!state.rawOnly;state.exts=[];}else{state.rawOnly=false;state.exts=state.exts.includes(f)?state.exts.filter(x=>x!==f):[...state.exts,f];}render();}else if(t?.dataset.sort){state.sort=t.dataset.sort;closePopovers();render();}else if(t?.dataset.folder)folder(t.dataset.folder);else if(t?.dataset.theme){document.documentElement.dataset.theme=t.dataset.theme;$$('.theme-toggle button').forEach(b=>b.classList.toggle('active',b.dataset.theme===t.dataset.theme));persist();}else if(t?.dataset.action==='open-single')setView('single');else if(t?.dataset.action==='all-metadata')allMetadata();else if(t?.id==='clearAllFilters')clearFilters();else if(t?.dataset.removeFilter){const f=t.dataset.removeFilter;if(f==='iso'){state.isoMin=state.isoMax='';$('#isoMin').value=$('#isoMax').value='';}else{state[f]=f==='starred'?false:'';const sel={camera:'#cameraFilter',orientation:'#orientationFilter',date:'#dateFilter'}[f];if(sel)$(sel).value='';}render();}if(!e.target.closest('.popover-anchor')&&!e.target.closest('.mini-tools-menu')&&!e.target.closest('#miniToolsButton'))closePopovers();});
 $('#photoGrid').addEventListener('dblclick',e=>{const b=e.target.closest('[data-select]');if(b){state.selected=b.dataset.select;setView('single');}});
 document.addEventListener('keydown',e=>{if($('#dialog').open)return;const edit=/INPUT|SELECT|TEXTAREA/.test(e.target.tagName);if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='f'){e.preventDefault();$('#search').focus();return;}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='o'){e.preventDefault();$('#folderInput').click();return;}if(edit)return;if(e.key==='ArrowRight'){e.preventDefault();move(1);}if(e.key==='ArrowLeft'){e.preventDefault();move(-1);}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const cols=state.view==='grid'?getComputedStyle($('#photoGrid')).gridTemplateColumns.split(' ').length:1;move(e.key==='ArrowUp'?-cols:cols);}if(e.key==='Enter'||e.key===' '){e.preventDefault();setView(state.view==='single'?'grid':'single');}if(e.key==='Escape'){closePopovers();if(state.fullscreen){state.fullscreen=false;$('#app').classList.remove('fullscreen');}else setView('grid');}if(e.key.toLowerCase()==='g')setView('grid');if(e.key.toLowerCase()==='i'){e.preventDefault();setInfo(!state.info);}if(e.key.toLowerCase()==='f'){if(state.view!=='single')setView('single');$('#fullscreenBtn').click();}if(e.key.toLowerCase()==='s')star(state.selected);});
}
function bindSort(){$('#sortOptions').innerHTML=sortDefs.map((s,i)=>`${i===0||s[0]!==sortDefs[i-1][0]?`<div class="sort-group-label">${s[0]}</div>`:''}<button class="sort-option ${state.sort===s[1]?'active':''}" data-sort="${s[1]}" aria-pressed="${state.sort===s[1]}"><span>${s[2]}</span>${state.sort===s[1]?icon('check'):''}</button>`).join('');iconize();}
async function loadLocalFiles(files){const imgs=files.filter(f=>(!f.webkitRelativePath||f.webkitRelativePath.split('/').length<=2)&&knownImages.has(f.name.split('.').pop().toUpperCase()));if(!imgs.length){toast('这个文件夹中没有找到支持的图片文件');return;}state.photos.filter(p=>p.local&&p.src).forEach(p=>URL.revokeObjectURL(p.src));state.photos=imgs.map((f,i)=>{const ext=f.name.split('.').pop().toUpperCase();const canPreview=!rawExts.has(ext)&&!['TIF','TIFF','HEIC','HEIF'].includes(ext);return {id:'local-'+i,name:f.name,ext,size:f.size,modified:new Date(f.lastModified).toISOString().slice(0,19),captured:null,camera:null,lens:null,iso:null,shutter:null,aperture:null,focal:null,width:null,height:null,starred:false,folder:'all',src:canPreview?URL.createObjectURL(f):null,demo:false,local:true};});state.local=true;state.folderName=files[0].webkitRelativePath?.split('/')[0]||'本地文件夹';folder('all');$('#folderDescription').textContent='本地浏览 · RAW 解码与 EXIF 读取尚未接入';$('.micro-label').textContent='LOCAL';toast(`已打开 ${imgs.length} 个图片文件`);await Promise.allSettled(state.photos.filter(p=>p.src).map(p=>new Promise(resolve=>{const img=new Image();img.onload=()=>{p.width=img.naturalWidth;p.height=img.naturalHeight;resolve();};img.onerror=()=>{URL.revokeObjectURL(p.src);p.src=null;resolve();};img.src=p.src;})));render();}
